  }
  void _message(String text) { if (!mounted) return; ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text), behavior: SnackBarBehavior.floating)); }
  @override void dispose() { _llama.dispose(); _tts.stop(); super.dispose(); }
  @override Widget build(BuildContext context) {
    if (_loading) return const Scaffold(body: Center(child: CircularProgressIndicator()));
    if (_profile.isEmpty) { WidgetsBinding.instance.addPostFrameCallback((_) { if (mounted && _profile.isEmpty) _onboard(); }); }
    final pages = <Widget>[
      HomePage(profile: _profile, sessions: _sessions, completed: _completed, onNavigate: (i) => setState(() => _index = i), onAdd: _addSession),
      TutorPage(profile: _profile, llama: _llama, modelStatus: _modelMessage, onModel: () => setState(() => _index = 6), onSaveNote: _saveAnswer, onSpeak: _speak),
      CalendarPage(sessions: _sessions, completed: _completed, onAdd: _addSession, onComplete: _completeSession, onDelete: _deleteSession),
      PlannerPage(sessions: _sessions, completed: _completed, onSessionsChanged: (list) async { _sessions = list; await _saveSessions(); }),
      NotesPage(notes: _notes, onSave: _saveNotes, onAdd: _addNote, onDelete: _deleteNote),
      ProgressPage(sessions: _sessions, completed: _completed, notes: _notes),
      ModelsPage(service: _models, status: _modelMessage, lowMemory: _lowMemory, onLowMemory: (v) => setState(() => _lowMemory = v), onLoad: _loadModel, onUnload: () async { await _llama.stop(); setState(() => _modelMessage = 'Model not loaded'); }, onMessage: _message),
      SettingsPage(profile: _profile, dark: _dark, onProfile: _onboard, onTheme: (v) { setState(() => _dark = v); widget.onThemeChanged(v); }, onAbout: () => showAboutDialog(context: context, applicationName: appName, applicationVersion: '1.0.0', children: const [Text('Designed and developed by Manoj Kumar, a student.'), Text('Flutter • Dart • llama.cpp • local model inference.'), Text('All student data stays on this PC. Model and library licenses are available on their official project pages.')]))
    ];
    final labels = ['Home','Learn','Calendar','Planner','Notes','Progress','Models','Settings']; final icons = [Icons.home_rounded,Icons.auto_awesome,Icons.calendar_month,Icons.event_note,Icons.sticky_note_2_outlined,Icons.insights,Icons.memory,Icons.settings_outlined];
    return Scaffold(body: SafeArea(child: Row(children: [if (MediaQuery.sizeOf(context).width > 760) NavigationRail(backgroundColor: Theme.of(context).colorScheme.surface, selectedIndex: _index, onDestinationSelected: (v) => setState(() => _index = v), labelType: NavigationRailLabelType.all, leading: Padding(padding: const EdgeInsets.symmetric(vertical: 18), child: Container(width: 48,height:48,decoration: BoxDecoration(gradient: const LinearGradient(colors:[brandBlue,brandViolet]),borderRadius: BorderRadius.circular(15)),child: const Icon(Icons.auto_awesome,color:Colors.white))), destinations: List.generate(labels.length,(i)=>NavigationRailDestination(icon:Icon(icons[i]),label:Text(labels[i])))), Expanded(child: Column(children: [Container(padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 14), decoration: const BoxDecoration(gradient: LinearGradient(colors:[brandBlue,brandViolet])), child: Row(children: [const Icon(Icons.menu_book_rounded,color:Colors.white,size:30), const SizedBox(width: 12), const Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[Text('StudyMate AI',style:TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.bold)),Text('Your personal learning companion',style:TextStyle(color:Colors.white70,fontSize:12))])), Container(padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7), decoration: BoxDecoration(color: Colors.white.withValues(alpha:.16), borderRadius: BorderRadius.circular(20)), child: const Row(children:[Icon(Icons.wifi_off,color:Colors.white,size:15),SizedBox(width:5),Text('Offline-first',style:TextStyle(color:Colors.white,fontSize:12))])), const SizedBox(width: 10), IconButton(tooltip:'Student profile',onPressed:_onboard,icon:const Icon(Icons.account_circle_outlined,color:Colors.white))])), Expanded(child: IndexedStack(index:_index,children:pages))]))]), bottomNavigationBar: MediaQuery.sizeOf(context).width <= 760 ? NavigationBar(selectedIndex:_index,onDestinationSelected:(v)=>setState(()=>_index=v), destinations:List.generate(labels.length,(i)=>NavigationDestination(icon:Icon(icons[i]),label:labels[i]))) : null));
  }
  Future<void> _addSession({DateTime? date}) async {
    final title = TextEditingController(); final subject = TextEditingController(); final start = TextEditingController(text:'16:00'); final end = TextEditingController(text:'17:00'); DateTime chosen = date ?? DateTime.now();
    await showDialog<void>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD)=>AlertDialog(title:const Text('Add study session'),content:SizedBox(width:400,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[_field(title,'Topic / activity'),_field(subject,'Subject'),Row(children:[Expanded(child:TextButton.icon(onPressed:()async{final d=await showDatePicker(context:ctx,initialDate:chosen,firstDate:DateTime(2020),lastDate:DateTime(2100));if(d!=null)setD(()=>chosen=d);},icon:const Icon(Icons.calendar_today),label:Text(DateFormat('EEE, d MMM').format(chosen)))),Expanded(child:_field(start,'Start (HH:mm)'))]),_field(end,'End (HH:mm)'),const Text('Reminder: the session will appear in your calendar. Keep StudyMate open to see upcoming-session alerts.')]))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()async{if(title.text.trim().isEmpty){return;} _sessions.add({'id':DateTime.now().microsecondsSinceEpoch.toString(),'title':title.text.trim(),'subject':subject.text.trim(),'date':DateFormat('yyyy-MM-dd').format(chosen),'start':start.text.trim(),'end':end.text.trim(),'created':DateTime.now().toIso8601String()});await _saveSessions();if(ctx.mounted)Navigator.pop(ctx);},child:const Text('Add session'))] )));
  }
