plain simply'),_prompt('Give an example')].map((w)=>ActionChip(label:Text((w as _PromptChip).label),onPressed:()=>_send((w as _PromptChip).label))).toList()),const SizedBox(height:8),Row(children:[Expanded(child:TextField(controller:_input,minLines:1,maxLines:4,onSubmitted:(_)=>_send(),decoration:InputDecoration(hintText:'Ask a doubt or paste an equation…',prefixIcon:const Icon(Icons.chat_bubble_outline),suffixIcon:IconButton(tooltip:'Attach a text file',onPressed:()async{final f=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['txt','md']);if(f!=null&&f.files.single.path!=null){_input.text='Please explain these study notes:\n${await File(f.files.single.path!).readAsString()}';}},icon:const Icon(Icons.attach_file))))),const SizedBox(width:8),IconButton.filled(onPressed:_busy?null:()=>_send(),icon:const Icon(Icons.send))]) ]));}
